function logRegisteredPubkey(
    bytes32 _signingGroupPubkeyX,
    bytes32 _signingGroupPubkeyY
) public returns (bool) {
    if (!approvedToLog(msg.sender)) return true;
    emit RegisteredPubkey(
        msg.sender,
        _signingGroupPubkeyX,
        _signingGroupPubkeyY,
        block.timestamp
    );
    return true;
}

